+const DOWNLOAD_TIMEOUT_MS = 60_000;
+const MAX_ARCHIVE_BYTES = 100 * 1024 * 1024;
+const MAX_SKILL_BYTES = 50 * 1024 * 1024;
+const MAX_LINK_DEPTH = 8;
